import { addDays, dayOfWeek, isValidISODate, mondayOf, timeToMinutes, todayISO, weekType } from '/shared/week.min.js?v=20261019_1';
import { ensureLessons, lessonsOf, store, tasks } from '../store.min.js?v=20261019_1';
import { handleTaskClick, shortSubject, subjectClass, taskHTML } from '../todo.min.js?v=20261019_1';
import {
  BELLS, DAY_FULL, DAY_SHORT, ROMAN, TYPE_CLASS, TYPE_LABEL,
  countPairs, dayNum, duration, esc, fmtDate, formatPairs, icon, isHalfPair, monthGen, monthNom, plural, reducedMotion, showFieldErrors, toast, withBusy,
} from '../ui.min.js?v=20261019_1';

const VIEW_KEY = 'uniplan-view';
const tm = timeToMinutes;
const pairs = formatPairs;
const nowMinutes = () => {
  const d = new Date();
  return d.getHours() * 60 + d.getMinutes();
};

function getView() {
  try {
    return localStorage.getItem(VIEW_KEY) === 'week' ? 'week' : 'day';
  } catch {
    return 'day';
  }
}

function state() {
  const date = store.selectedDate;
  const today = todayISO();
  const calWeek = weekType(date, store.group.semesterStart);
  const week = store.weekOverride ?? calWeek;
  const monday = mondayOf(date);
  return {
    date, today, calWeek, week, monday, dow: dayOfWeek(date),

    liveWeek: monday === mondayOf(today) && week === calWeek,
  };
}

function weekRangeLabel(monday) {
  const sunday = addDays(monday, 6);
  return monthGen(monday) === monthGen(sunday)
    ? `${dayNum(monday)}–${dayNum(sunday)} ${monthGen(sunday)}`
    : `${fmtDate(monday)} – ${fmtDate(sunday)}`;
}

const openCount = (date) => tasks.list(date).filter((t) => !t.done).length;

function lessonStatus(s, l, date) {
  if (!s.liveWeek || date !== s.today) return '';
  const m = nowMinutes();
  if (m >= tm(l.end)) return 'is-past';
  if (m >= tm(l.start)) return 'is-now';
  return '';
}

function skeleton() {
  return `<div class="sched" aria-busy="true">
    <div class="skeleton" style="height:84px"></div>
    <div class="skeleton" style="height:84px"></div>
    <div class="skeleton" style="height:110px"></div>
    <div class="skeleton" style="height:110px"></div>
  </div>`;
}

function titleHTML(s) {
  return `
    <p class="eyebrow">${esc(store.group.name)} · ${monthNom(s.date)}</p>
    <h1>${DAY_FULL[s.dow]}</h1>
    <div class="date-line">${fmtDate(s.date)}${s.date === s.today ? '<span class="pill">сегодня</span>' : ''}</div>`;
}

function hintHTML(s) {
  if (store.weekOverride === null || store.weekOverride === s.calWeek) return '';
  return `<div class="week-hint">
    <span>Показана ${ROMAN[s.week]} неделя, а по календарю сейчас ${ROMAN[s.calWeek]}</span>
    <button class="btn btn-sm" type="button" data-act="reset-week">${icon('undo', 15, 2.2)} Вернуть ${ROMAN[s.calWeek]}</button>
  </div>`;
}

function weekbarHTML(s, view) {
  return `
    <button class="icon-btn" type="button" data-act="prev-week" aria-label="Предыдущая неделя">${icon('left', 20, 2.2)}</button>
    <div class="weekbar-label">${weekRangeLabel(s.monday)}<small>${ROMAN[s.calWeek]} неделя</small></div>
    ${s.date !== s.today ? '<button class="btn btn-sm" type="button" data-act="today">Сегодня</button>' : ''}
    <button class="icon-btn" type="button" data-act="next-week" aria-label="Следующая неделя">${icon('right', 20, 2.2)}</button>
    <div class="seg viewseg" role="group" aria-label="Вид">
      <button type="button" data-view="day" aria-pressed="${view === 'day'}">День</button>
      <button type="button" data-view="week" aria-pressed="${view === 'week'}">Неделя</button>
    </div>`;
}

function daysHTML(s) {
  let html = '';
  for (let i = 0; i < 7; i++) {
    const d = addDays(s.monday, i);
    const dow = i + 1;
    const ls = lessonsOf(dow, s.week);
    const pairCount = countPairs(ls);
    const open = openCount(d);
    const cls = ['day', dow >= 6 && 'is-weekend', d === s.today && 'is-today'].filter(Boolean).join(' ');
    html += `
      <button class="${cls}" type="button" role="tab" data-date="${d}" aria-selected="${d === s.date}"
        aria-label="${DAY_FULL[dow]}, ${fmtDate(d)}: ${pairs(pairCount)}${open ? `, открытых дел: ${open}` : ''}">
        <span class="day-dow">${DAY_SHORT[dow]}</span>
        <span class="day-num">${dayNum(d)}</span>
        <span class="day-bars" aria-hidden="true">${ls.map((l) => `<i class="${TYPE_CLASS[l.type]}"></i>`).join('')}<span class="bar-label">${ls.length ? pairs(pairCount) : 'свободно'}</span></span>
        ${open ? `<span class="day-badge" aria-hidden="true">${open}</span>` : ''}
      </button>`;
  }
  return html;
}

function segHTML(s) {
  const n = countPairs(lessonsOf(s.dow, s.week));
  const isUnapproved = store.user?.role === 'student' && store.user?.approved === false;
  const list = tasks.list(s.date);
  const done = list.filter((t) => t.done).length;
  const countBadge = isUnapproved ? `<span class="count">${icon('lock', 11, 2.4)}</span>` : `<span class="count">${done}/${list.length}</span>`;
  return `
    <button type="button" role="tab" data-pane-btn="lessons" aria-selected="${store.mobilePane === 'lessons'}">Пары <span class="count">${n}</span></button>
    <button type="button" role="tab" data-pane-btn="todo" aria-selected="${store.mobilePane === 'todo'}">Дела ${countBadge}</button>`;
}

function nowCardHTML(ls) {
  const m = nowMinutes();
  const cur = ls.find((l) => tm(l.start) <= m && m < tm(l.end));
  let label;
  let big;
  let sub;
  let pct = null;
  if (cur) {
    label = 'Сейчас идёт';
    big = `ещё ${duration(tm(cur.end) - m)}`;
    sub = `${cur.subject} · ауд. ${cur.room}`;
    pct = ((m - tm(cur.start)) / (tm(cur.end) - tm(cur.start))) * 100;
  } else {
    const next = ls.find((l) => tm(l.start) > m);
    const prev = [...ls].reverse().find((l) => tm(l.end) <= m);
    if (next) {
      label = prev ? 'Перерыв' : 'До первой пары';
      big = `через ${duration(tm(next.start) - m)}`;
      sub = `${next.start} · ${next.subject} · ауд. ${next.room}`;
      if (prev) pct = ((m - tm(prev.end)) / (tm(next.start) - tm(prev.end))) * 100;
    } else {
      const open = openCount(store.selectedDate);
      label = 'На сегодня всё';
      big = 'Пары закончились';
      sub = open ? `Открытых дел на сегодня: ${open}` : 'И дела на сегодня закрыты';
    }
  }
  return `<div class="now" role="status">
    <span class="now-label"><i aria-hidden="true"></i>${label}</span>
    <span class="now-big">${esc(big)}</span>
    <span class="now-sub">${esc(sub)}</span>
    ${pct !== null ? `<div class="now-bar" aria-hidden="true"><i style="width:${Math.max(3, Math.min(100, pct)).toFixed(1)}%"></i></div>` : ''}
  </div>`;
}

function sameSubject(a, b) {
  if (!a || !b) return false;
  return String(a).trim().toLowerCase() === String(b).trim().toLowerCase();
}

function sameType(a, b) {
  if (!a || !b) return false;
  return String(a).trim().toLowerCase() === String(b).trim().toLowerCase();
}

function groupLessonsForDisplay(lessons) {
  if (!lessons || !lessons.length) return [];
  const sorted = [...lessons].sort((a, b) => a.start.localeCompare(b.start));
  const groups = [];

  let i = 0;
  while (i < sorted.length) {
    const l1 = sorted[i];
    const dur1 = tm(l1.end) - tm(l1.start);

    if (i + 1 < sorted.length) {
      const l2 = sorted[i + 1];
      const dur2 = tm(l2.end) - tm(l2.start);
      const gap = tm(l2.start) - tm(l1.end);
      const span = tm(l2.end) - tm(l1.start);
      const sameSubj = sameSubject(l1.subject, l2.subject);
      const sameKind = sameType(l1.type, l2.type);

      const areTwoHalves = sameSubj && sameKind && (dur1 <= 60 && dur2 <= 60 && gap >= 0 && gap <= 20 && span <= 120);
      const areSubgroups = sameSubj && sameKind && (l1.start === l2.start && l1.end === l2.end);

      if (areTwoHalves || areSubgroups) {
        groups.push({
          isGroup: true,
          type: areSubgroups ? 'subgroups' : 'halves',
          start: l1.start,
          end: l2.end,
          lessons: [l1, l2]
        });
        i += 2;
        continue;
      }
    }

    groups.push({
      isGroup: false,
      type: dur1 <= 60 ? 'single-half' : 'single-full',
      start: l1.start,
      end: l1.end,
      lessons: [l1]
    });
    i += 1;
  }

  return groups;
}

function findPairNumber(startTime, fallbackIdx) {
  const mins = tm(startTime);
  if (mins >= 450 && mins < 580) return 1;
  if (mins >= 580 && mins < 695) return 2;
  if (mins >= 695 && mins < 805) return 3;
  if (mins >= 805 && mins < 915) return 4;
  if (mins >= 915 && mins < 1025) return 5;
  if (mins >= 1025 && mins < 1135) return 6;
  if (mins >= 1135 && mins <= 1260) return 7;
  return fallbackIdx + 1;
}

function roomBadgeHTML(room) {
  const isMultiRoom = /[,;/]/.test(room) || room.length > 10;
  return isMultiRoom
    ? `<button type="button" class="room room-more" data-act="toggle-room" data-room="${esc(room)}" aria-expanded="false" aria-label="Показать аудитории: ${esc(room)}" title="${esc(room)}">...</button>`
    : `<span class="room">${esc(room)}</span>`;
}

function deckCardHTML(l, idx, isActive, m, s, isGroup = false) {
  const status = lessonStatus(s, l, s.date);
  const half = !isGroup && isHalfPair(l);
  const typeClass = TYPE_CLASS[l.type] || 't-other';
  const isUnapproved = store.user?.role === 'student' && store.user?.approved === false;
  return `
    <div class="deck-card ${typeClass} ${status} ${isActive ? 'is-active' : 'is-peek'}"
         data-card-idx="${idx}"
         data-sub-lesson="${l.id || idx}"
         ${!isActive ? 'data-act="pick-subcard" role="button" tabindex="0" aria-label="Показать второе занятие"' : ''}>
      <div class="deck-card-top">
        <div class="deck-card-tags">
          <div class="tag-row">
            <span class="tag">${TYPE_LABEL[l.type] || l.type || 'Занятие'}</span>
            ${half ? '<span class="tag tag-week">полупара</span>' : ''}
            ${status === 'is-now' ? `<span class="tag tag-live">идёт · ещё ${duration(tm(l.end) - m)}</span>` : ''}
          </div>
          ${l.week ? `<div class="tag-row tag-sub-row"><span class="tag tag-week">только ${ROMAN[l.week]}</span></div>` : ''}
        </div>
        <div class="deck-card-room-slot">
          ${roomBadgeHTML(l.room)}
        </div>
      </div>
      <h3 class="deck-card-title">${esc(l.subject)}</h3>
      <div class="deck-card-foot">
        <span class="deck-teacher">${esc(l.teacher)}</span>
        ${isUnapproved ? '' : `<button class="lesson-add" type="button" data-act="task-for" data-subject="${esc(l.subject)}">${icon('plus', 13, 2.6)} задача</button>`}
      </div>
    </div>`;
}

function lessonsHTML(s, anim) {
  const ls = lessonsOf(s.dow, s.week);
  if (!ls.length) {
    const other = s.week === 1 ? 2 : 1;
    const n = countPairs(lessonsOf(s.dow, other));
    return `<div class="empty-day ${anim}">
      <span class="ic">${icon(s.dow === 7 ? 'sun' : 'coffee', 24, 2)}</span>
      <span class="big">${s.dow === 7 ? 'Выходной' : 'Пар нет'}</span>
      <p class="muted">${n
        ? `А в ${ROMAN[other]} неделю в этот день ${pairs(n)}.`
        : 'Свободный день — можно запланировать дела.'}</p>
      ${n ? `<button class="btn btn-sm" type="button" data-week="${other}">Показать ${ROMAN[other]} неделю</button>` : ''}
    </div>`;
  }

  const m = nowMinutes();
  const live = s.liveWeek && s.date === s.today;
  let html = live ? nowCardHTML(ls) : '';
  html += `<div class="lessons ${anim}">`;

  const groups = groupLessonsForDisplay(ls);
  groups.forEach((g, gIdx) => {
    if (gIdx > 0) {
      const prevEnd = groups[gIdx - 1].end;
      const gap = tm(g.start) - tm(prevEnd);
      if (gap >= 30) html += `<div class="gap-note" style="--i:${gIdx}">${icon('coffee', 14, 2)} окно ${duration(gap)}</div>`;
    }

    const pairNo = findPairNumber(g.start, gIdx);

    if (g.isGroup) {
      const [lA, lB] = g.lessons;
      const isLiveDay = s.liveWeek && s.date === s.today;
      const inPart1 = isLiveDay && m >= tm(lA.start) && m < tm(lA.end);
      const inBreak = isLiveDay && m >= tm(lA.end) && m < tm(lB.start);
      const inPart2 = isLiveDay && m >= tm(lB.start) && m <= tm(lB.end);

      const stA = lessonStatus(s, lA, s.date);
      const stB = lessonStatus(s, lB, s.date);
      const isNow = inPart1 || inBreak || inPart2;
      const isPast = isLiveDay && m > tm(lB.end);
      const groupStatus = isNow ? 'is-now' : (isPast ? 'is-past' : '');
      const primaryType = TYPE_CLASS[lA.type] || 't-other';

      const gapBetween = tm(lB.start) - tm(lA.end);
      const activeIdx = (inPart2 || inBreak || (stB === 'is-now' && !inPart1)) ? 1 : 0;
      const initialPhase = inPart1 ? 'part1' : (inBreak ? 'break' : (inPart2 ? 'part2' : (isPast ? 'past' : 'upcoming')));

      const timelineHTML = (g.type === 'halves' && gapBetween >= 0)
        ? `
          <div class="pair-timeline">
            <span class="pair-no" title="Пара №${pairNo}">${pairNo}</span>
            <span class="tl-time tl-start">${lA.start}</span>
            <i class="tl-line" aria-hidden="true"></i>
            <span class="tl-time tl-sub${inPart1 ? ' is-live-target' : ''}">${lA.end}</span>
            ${gapBetween > 0 ? `
              <div class="tl-break${inBreak ? ' is-break-now' : ''}">
                <span>перерыв</span>
                <b>${gapBetween} мин</b>
              </div>
            ` : ''}
            <span class="tl-time tl-sub${inPart2 ? ' is-live-target' : ''}">${lB.start}</span>
            <i class="tl-line" aria-hidden="true"></i>
            <span class="tl-time tl-end">${lB.end}</span>
          </div>
        `
        : `
          <div class="pair-timeline is-single">
            <span class="pair-no" title="Пара №${pairNo}">${pairNo}</span>
            <span class="tl-time tl-start">${g.start}</span>
            <i class="tl-line" aria-hidden="true"></i>
            <span class="tl-time tl-end">${g.end}</span>
          </div>
        `;

      html += `
        <article class="lesson is-composite ${primaryType} ${groupStatus}" data-lesson-group="${gIdx}" data-live-phase="${initialPhase}" style="--i:${gIdx}" aria-label="Пара №${pairNo}, ${g.start}–${g.end}, ${esc(lA.subject)}">
          <div class="pair-card-deck">
            ${timelineHTML}
            <div class="pair-accent-bar" aria-hidden="true"></div>
            <div class="pair-cards-stack">
              ${deckCardHTML(lA, 0, activeIdx === 0, m, s, true)}
              ${deckCardHTML(lB, 1, activeIdx === 1, m, s, true)}
            </div>
          </div>
        </article>`;
    } else {
      const l = g.lessons[0];
      const half = isHalfPair(l);
      const badgeLabel = half ? '½' : pairNo;
      const badgeTitle = half ? 'Полупара (0.5 пары)' : `Пара №${pairNo}`;
      const status = lessonStatus(s, l, s.date);
      const primaryType = TYPE_CLASS[l.type] || 't-other';

      html += `
        <article class="lesson ${primaryType} ${status}" data-lesson-group="${gIdx}" style="--i:${gIdx}" aria-label="${esc(`${l.start}–${l.end}, ${l.subject}, ${TYPE_LABEL[l.type]}, аудитория ${l.room}`)}">
          <div class="pair-card-deck">
            <div class="pair-timeline is-single">
              <span class="pair-no" title="${badgeTitle}">${badgeLabel}</span>
              <span class="tl-time tl-start">${l.start}</span>
              <i class="tl-line" aria-hidden="true"></i>
              <span class="tl-time tl-end">${l.end}</span>
            </div>
            <div class="pair-accent-bar" aria-hidden="true"></div>
            <div class="pair-cards-stack">
              ${deckCardHTML(l, 0, true, m, s, false)}
            </div>
          </div>
        </article>`;
    }
  });

  return `${html}</div>`;
}

function gridRows(s) {
  const extra = new Map();
  let lastBell = -1;
  for (let d = 1; d <= 7; d++) {
    for (const l of lessonsOf(d, s.week)) {
      const b = BELLS.findIndex(([start]) => start === l.start);
      if (b >= 0) lastBell = Math.max(lastBell, b);
      else extra.set(l.start, l.end);
    }
  }
  const rows = [];
  if (lastBell >= 0 || extra.size === 0) {
    const count = Math.max(lastBell + 1, 4);
    for (let i = 0; i < count; i++) {
      rows.push({ no: i + 1, start: BELLS[i][0], end: BELLS[i][1] });
    }
  }
  for (const [start, end] of extra) rows.push({ no: null, start, end });
  return rows.sort((a, b) => a.start.localeCompare(b.start));
}

const weekDays = (s) => [1, 2, 3, 4, 5, 6, 7].map((dow) => ({ dow, date: addDays(s.monday, dow - 1) }));

function gridHeadHTML(s) {
  const head = weekDays(s).map(({ dow, date }) => {
    const open = openCount(date);
    const cls = ['tt-day', date === s.date && 'is-selected', date === s.today && 'is-today'].filter(Boolean).join(' ');
    return `<th class="${cls}" scope="col">
      <button type="button" data-date="${date}" aria-pressed="${date === s.date}" aria-label="${DAY_FULL[dow]}, ${fmtDate(date)}${open ? `, открытых дел: ${open}` : ''}">
        <span class="dow">${DAY_SHORT[dow]}${open ? `<span class="day-badge" aria-hidden="true">${open}</span>` : ''}</span>
        <span class="date">${date === s.today ? 'сегодня' : `${dayNum(date)} ${monthGen(date).slice(0, 3)}`}</span>
      </button>
    </th>`;
  }).join('');
  return `<thead><tr><th class="tt-corner" scope="col">Время</th>${head}</tr></thead>`;
}

function gridHTML(s) {
  const rows = gridRows(s);
  const days = weekDays(s);
  const sundayEmpty = !lessonsOf(7, s.week).length;
  let k = 0;

  const body = rows.map((r) => `
    <tr>
      <th class="tt-time" scope="row">${r.no ? `<b>${r.no} пара</b>` : ''}<span>${r.start}</span><span>${r.end}</span></th>
      ${days.map(({ dow, date }) => {
        const sel = date === s.date ? ' is-selected' : '';
        const l = lessonsOf(dow, s.week).find((x) => x.start === r.start);
        if (!l) return `<td class="tt-cell${sel}" data-date="${date}"></td>`;
        return `<td class="tt-cell${sel}" data-date="${date}">
          <div class="tt-lesson ${TYPE_CLASS[l.type]} ${lessonStatus(s, l, date)}" style="--i:${k++}"
            title="${esc(`${l.subject}\n${TYPE_LABEL[l.type]}, ауд. ${l.room}${l.teacher ? `\n${l.teacher}` : ''}`)}">
            <div class="s">${esc(l.subject)}</div>
            <div class="m">${TYPE_LABEL[l.type]} · <span class="r">${esc(l.room)}</span></div>
          </div>
        </td>`;
      }).join('')}
    </tr>`).join('');

  return `<div class="tt-scroll"><table class="tt">
    <colgroup><col style="width:78px">${days.map(({ dow }) => `<col${dow === 7 && sundayEmpty ? ' style="width:72px"' : ''}>`).join('')}</colgroup>
    ${gridHeadHTML(s)}
    <tbody>${body}</tbody>
  </table></div>`;
}

function todoFootHTML(total, done) {
  if (!total) return '<p class="todo-empty">На этот день задач нет. Добавьте первую — например, подготовку к паре.</p>';
  if (done === total) return `<div class="stamp-wrap"><span class="stamp">${icon('check', 16, 2.6)} Всё сделано</span></div>`;
  return '';
}

function todoHTML(s) {
  const isUnapproved = store.user?.role === 'student' && store.user?.approved === false;
  if (isUnapproved) {
    return `
      <section class="card todo" aria-label="Дела недоступны">
        <div class="card-head" style="margin:0">
          <h2 class="todo-title">Дела<small>${DAY_FULL[s.dow]}, ${fmtDate(s.date)}</small></h2>
          <span class="todo-count">${icon('lock', 12, 2.2)}</span>
        </div>
        <div class="todo-locked" style="padding:28px 14px;text-align:center;display:grid;place-items:center;gap:10px">
          <div style="width:44px;height:44px;border-radius:50%;background:var(--surface-2);display:grid;place-items:center;color:var(--ink-2)">
            ${icon('lock', 22, 2)}
          </div>
          <div style="font-weight:700;font-size:15px">Дела станут доступны после одобрения</div>
          <p class="muted" style="font-size:13px;line-height:1.45;margin:0;max-width:280px">
            Заявка на вступление в группу <b>${esc(store.group.name)}</b> ожидает подтверждения старосты.
          </p>
        </div>
      </section>`;
  }

  const list = tasks.list(s.date);
  const done = list.filter((t) => t.done).length;
  const subjects = [...new Set(lessonsOf(s.dow, s.week).map((l) => l.subject))];
  if (store.todoSubject && !subjects.includes(store.todoSubject)) subjects.unshift(store.todoSubject);
  const isStarosta = store.user?.role === 'starosta';
  return `
    <section class="card todo" aria-label="Дела на ${fmtDate(s.date)}">
      <div class="card-head" style="margin:0">
        <h2 class="todo-title">Дела<small>${DAY_FULL[s.dow]}, ${fmtDate(s.date)}</small></h2>
        <span class="todo-count" data-slot="count" aria-label="Выполнено ${done} из ${list.length}">${done} / ${list.length}</span>
      </div>
      <form class="todo-form" data-form="todo" novalidate>
        <div class="todo-row">
          <label class="sr-only" for="todo-input">Новая задача</label>
          <input id="todo-input" class="input" name="text" maxlength="200" autocomplete="off" placeholder="Например: сдать лабу №3">
          <button class="btn btn-primary" type="submit" aria-label="Добавить задачу">${icon('plus', 18, 2.6)}<span class="hide-xs">Добавить</span></button>
        </div>
        ${isStarosta ? `
          <div class="todo-scope-toggle">
            <button type="button" class="chip-group-toggle" data-act="toggle-group-task" aria-pressed="false" title="Создать как общее дело для всей группы">
              ${icon('users', 14, 2.2)}<span>Для всей группы</span>
            </button>
          </div>
        ` : ''}
        ${subjects.length ? `<div class="todo-subjects" role="group" aria-label="Привязать задачу к предмету">
          ${subjects.map((sub) => `<button type="button" class="chip ${subjectClass(sub)}" data-tone data-subject="${esc(sub)}" aria-pressed="${sub === store.todoSubject}" title="${esc(sub)}">${esc(shortSubject(sub))}</button>`).join('')}
        </div>` : ''}
        <small class="field-error" data-error="text"></small>
      </form>
      <ul class="todo-list" data-slot="todo-list">${list.map((t) => taskHTML(t)).join('')}</ul>
      <div data-slot="todo-foot">${todoFootHTML(list.length, done)}</div>
    </section>`;
}

export async function render(root, params) {
  if (params.date && isValidISODate(params.date)) {
    if (!store.selectedDate || mondayOf(params.date) !== mondayOf(store.selectedDate)) store.weekOverride = null;
    store.selectedDate = params.date;
  }
  if (!store.selectedDate) store.selectedDate = todayISO();
  let view = getView();

  root.innerHTML = skeleton();
  await Promise.all([ensureLessons(), tasks.loadWeek(mondayOf(store.selectedDate))]);

  const slot = (name) => root.querySelector(`[data-slot="${name}"]`);

  function paintAll(anim = 'anim-in') {
    const s = state();
    const isUnapproved = store.user?.role === 'student' && store.user?.approved === false;
    const approvalBanner = isUnapproved ? `
      <div class="banner banner-pending" style="display:flex;align-items:center;gap:10px;padding:12px 16px;border-radius:var(--r);background:var(--surface-2);border:1px solid var(--border);color:var(--ink);margin-bottom:16px;font-size:14px;box-shadow:var(--shadow-sm)">
        <span style="color:var(--live);display:flex">${icon('alert', 18, 2.2)}</span>
        <span>Заявка на вступление в группу <b>${esc(store.group.name)}</b> ожидает подтверждения старосты. Расписание доступно, а дела откроются после одобрения.</span>
      </div>` : '';
    document.documentElement.dataset.week = String(s.week);
    root.innerHTML = `
      <section class="sched${view === 'week' ? ' is-week' : ''}">
        ${approvalBanner}
        <header class="sched-head">
          <div class="sched-title" data-slot="title">${titleHTML(s)}</div>
          <div class="wswitch" data-active="${s.week}">
            <span class="wswitch-label" id="wlabel">неделя</span>
            <div class="wswitch-track" role="radiogroup" aria-labelledby="wlabel">
              <span class="wswitch-knob" aria-hidden="true"></span>
              <button type="button" role="radio" data-week="1" aria-checked="${s.week === 1}" aria-label="Первая неделя">I</button>
              <button type="button" role="radio" data-week="2" aria-checked="${s.week === 2}" aria-label="Вторая неделя">II</button>
            </div>
          </div>
        </header>
        <div data-slot="hint">${hintHTML(s)}</div>
        <div class="weekbar" data-slot="weekbar">${weekbarHTML(s, view)}</div>
        <div class="days" role="tablist" aria-label="Дни недели" data-slot="days">${daysHTML(s)}</div>
        <div class="seg mobile-seg" role="tablist" aria-label="Раздел дня" data-slot="seg">${segHTML(s)}</div>
        <div class="day-grid" data-show="${store.mobilePane}">
          <div class="main-col" data-pane="lessons">
            <div class="lessons-col" data-slot="lessons">${lessonsHTML(s, anim)}</div>
            <div class="card tt-card week-view" data-slot="grid">${gridHTML(s)}</div>
          </div>
          <aside class="todo-col" data-pane="todo" data-slot="todo">${todoHTML(s)}</aside>
        </div>
      </section>`;
  }

  function paintDay(anim = 'anim-in') {
    const s = state();
    document.documentElement.dataset.week = String(s.week);
    const sw = root.querySelector('.wswitch');
    sw.dataset.active = String(s.week);
    sw.querySelectorAll('[data-week]').forEach((b) => b.setAttribute('aria-checked', String(Number(b.dataset.week) === s.week)));
    slot('title').innerHTML = titleHTML(s);
    slot('hint').innerHTML = hintHTML(s);
    slot('weekbar').innerHTML = weekbarHTML(s, view);
    slot('days').innerHTML = daysHTML(s);
    slot('seg').innerHTML = segHTML(s);
    slot('lessons').innerHTML = lessonsHTML(s, anim);
    slot('grid').innerHTML = gridHTML(s);
    slot('todo').innerHTML = todoHTML(s);
  }

  function paintCounts() {
    const s = state();
    const list = tasks.list(s.date);
    const done = list.filter((t) => t.done).length;
    const count = slot('count');
    if (count) {
      count.textContent = `${done} / ${list.length}`;
      count.setAttribute('aria-label', `Выполнено ${done} из ${list.length}`);
    }
    const foot = slot('todo-foot');
    if (foot) foot.innerHTML = todoFootHTML(list.length, done);
    slot('days').innerHTML = daysHTML(s);
    slot('seg').innerHTML = segHTML(s);
    const thead = slot('grid')?.querySelector('thead');
    if (thead) thead.outerHTML = gridHeadHTML(s);
  }

  const syncUrl = () => history.replaceState(null, '', `#/schedule?date=${store.selectedDate}`);

  async function selectDate(date, anim = 'anim-in') {
    const sameWeek = mondayOf(date) === mondayOf(store.selectedDate);
    store.selectedDate = date;
    store.todoSubject = null;
    syncUrl();
    if (!sameWeek) {
      store.weekOverride = null;
      try {
        await tasks.loadWeek(mondayOf(date));
      } catch (err) {
        toast(err.message, 'error');
      }
    }
    paintDay(anim);
  }

  function setWeek(week) {
    const s = state();
    if (week === s.week) return;
    store.weekOverride = week === s.calWeek ? null : week;
    paintDay(reducedMotion() ? '' : 'anim-flip');
  }

  function setView(next) {
    view = next;
    try {
      localStorage.setItem(VIEW_KEY, view);
    } catch {

    }
    root.querySelector('.sched').classList.toggle('is-week', view === 'week');
    root.querySelectorAll('[data-view]').forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.view === view)));
    if (view === 'week') slot('grid').innerHTML = gridHTML(state());
    else slot('lessons').innerHTML = lessonsHTML(state(), 'anim-in');
  }

  function setPane(pane) {
    store.mobilePane = pane;
    root.querySelector('.day-grid').dataset.show = pane;
    slot('seg').innerHTML = segHTML(state());
  }

  const onClick = (e) => {
    if (handleTaskClick(e, () => paintCounts())) return;
    const t = e.target;

    const pickCard = t.closest('[data-act="pick-subcard"]');
    if (pickCard) {
      const stack = pickCard.closest('.pair-cards-stack');
      if (stack) {
        const cards = stack.querySelectorAll('.deck-card');
        cards.forEach((c) => {
          if (c === pickCard) {
            c.classList.remove('is-peek');
            c.classList.add('is-active');
            c.removeAttribute('data-act');
            c.removeAttribute('role');
            c.removeAttribute('tabindex');
            c.removeAttribute('aria-label');
          } else {
            c.classList.remove('is-active');
            c.classList.add('is-peek');
            c.setAttribute('data-act', 'pick-subcard');
            c.setAttribute('role', 'button');
            c.setAttribute('tabindex', '0');
            c.setAttribute('aria-label', 'Показать другое занятие');
          }
        });
      }
      return;
    }

    const roomBtn = t.closest('[data-act="toggle-room"]');
    if (roomBtn) {
      const open = roomBtn.getAttribute('aria-expanded') === 'true';
      root.querySelectorAll('[data-act="toggle-room"][aria-expanded="true"]').forEach((b) => {
        b.setAttribute('aria-expanded', 'false');
        b.textContent = '...';
      });
      if (!open) {
        roomBtn.setAttribute('aria-expanded', 'true');
        roomBtn.textContent = roomBtn.dataset.room;
      }
      return;
    }
    root.querySelectorAll('[data-act="toggle-room"][aria-expanded="true"]').forEach((b) => {
      b.setAttribute('aria-expanded', 'false');
      b.textContent = '...';
    });

    const groupToggle = t.closest('[data-act="toggle-group-task"]');
    if (groupToggle) {
      const pressed = groupToggle.getAttribute('aria-pressed') === 'true';
      groupToggle.setAttribute('aria-pressed', String(!pressed));
      groupToggle.classList.toggle('is-active', !pressed);
      return;
    }

    const weekBtn = t.closest('button[data-week]');
    if (weekBtn) return setWeek(Number(weekBtn.dataset.week));
    const viewBtn = t.closest('[data-view]');
    if (viewBtn) return setView(viewBtn.dataset.view);
    const dayEl = t.closest('[data-date]');
    if (dayEl) {
      if (dayEl.dataset.date !== store.selectedDate) selectDate(dayEl.dataset.date);
      return;
    }
    const paneBtn = t.closest('[data-pane-btn]');
    if (paneBtn) return setPane(paneBtn.dataset.paneBtn);

    const chip = t.closest('.chip[data-subject]');
    if (chip) {
      store.todoSubject = store.todoSubject === chip.dataset.subject ? null : chip.dataset.subject;
      root.querySelectorAll('.todo-subjects .chip').forEach((c) => c.setAttribute('aria-pressed', String(c.dataset.subject === store.todoSubject)));
      return;
    }

    const act = t.closest('[data-act]')?.dataset.act;
    if (act === 'prev-week') selectDate(addDays(store.selectedDate, -7));
    else if (act === 'next-week') selectDate(addDays(store.selectedDate, 7));
    else if (act === 'today') selectDate(todayISO());
    else if (act === 'reset-week') setWeek(state().calWeek);
    else if (act === 'task-for') {
      store.todoSubject = t.closest('[data-subject]').dataset.subject;
      setPane('todo');
      slot('todo').innerHTML = todoHTML(state());
      const input = root.querySelector('#todo-input');
      input.focus({ preventScroll: true });
      input.scrollIntoView({ behavior: reducedMotion() ? 'auto' : 'smooth', block: 'center' });
    }
  };

  const onSubmit = async (e) => {
    const form = e.target.closest('[data-form="todo"]');
    if (!form) return;
    e.preventDefault();
    const input = form.elements.text;
    const text = input.value.trim();
    if (!text) {
      showFieldErrors(form, { details: [{ path: 'text', message: 'Напишите, что нужно сделать' }] });
      return input.focus();
    }
    showFieldErrors(form, null);
    const isGroup = form.querySelector('[data-act="toggle-group-task"]')?.getAttribute('aria-pressed') === 'true';
    try {
      const task = await withBusy(form.querySelector('[type="submit"]'), () => tasks.add(store.selectedDate, text, store.todoSubject, isGroup));
      store.todoSubject = null;
      input.value = '';
      const groupToggle = form.querySelector('[data-act="toggle-group-task"]');
      if (groupToggle) {
        groupToggle.setAttribute('aria-pressed', 'false');
        groupToggle.classList.remove('is-active');
      }
      root.querySelectorAll('.todo-subjects .chip').forEach((c) => c.setAttribute('aria-pressed', 'false'));
      const listEl = slot('todo-list');
      const tmp = document.createElement('template');
      tmp.innerHTML = taskHTML(task).trim();
      listEl.insertBefore(tmp.content.firstChild, listEl.querySelector('.is-done'));
      paintCounts();
      input.focus();
    } catch (err) {
      if (!showFieldErrors(form, err)) toast(err.message, 'error');
    }
  };

  let touch = null;
  const onTouchStart = (e) => {
    touch = e.target.closest('.lessons-col') ? { x: e.touches[0].clientX, y: e.touches[0].clientY } : null;
  };
  const onTouchEnd = (e) => {
    if (!touch) return;
    const dx = e.changedTouches[0].clientX - touch.x;
    const dy = e.changedTouches[0].clientY - touch.y;
    touch = null;
    if (Math.abs(dx) > 70 && Math.abs(dy) < 50) selectDate(addDays(store.selectedDate, dx < 0 ? 1 : -1));
  };

  const onKey = (e) => {
    const pickCard = e.target.closest('[data-act="pick-subcard"]');
    if (pickCard && (e.key === 'Enter' || e.key === ' ')) {
      e.preventDefault();
      pickCard.click();
      return;
    }
    if (!e.target.closest('[data-date]') || (e.key !== 'ArrowLeft' && e.key !== 'ArrowRight')) return;
    e.preventDefault();
    selectDate(addDays(store.selectedDate, e.key === 'ArrowRight' ? 1 : -1)).then(() => {
      root.querySelector(`.day[data-date="${store.selectedDate}"], .tt-day [data-date="${store.selectedDate}"]`)?.focus();
    });
  };

  function updateCardLive(card, l, s, m) {
    if (!card) return;
    const st = lessonStatus(s, l, s.date);
    card.classList.toggle('is-now', st === 'is-now');
    card.classList.toggle('is-past', st === 'is-past');
    let liveTag = card.querySelector('.tag-live');
    if (st === 'is-now') {
      const txt = `идёт · ещё ${duration(tm(l.end) - m)}`;
      if (liveTag) {
        if (liveTag.textContent !== txt) liveTag.textContent = txt;
      } else {
        const targetRow = card.querySelector('.deck-card-tags .tag-row') || card.querySelector('.deck-card-top');
        if (targetRow) {
          const span = document.createElement('span');
          span.className = 'tag tag-live';
          span.textContent = txt;
          targetRow.appendChild(span);
        }
      }
    } else if (liveTag) {
      liveTag.remove();
    }
  }

  function updateLiveStatus(s) {
    const container = slot('lessons');
    if (!container) return;
    const ls = lessonsOf(s.dow, s.week);
    if (!ls.length) return;

    const existingNow = container.querySelector('.now');
    if (existingNow) {
      const tmp = document.createElement('div');
      tmp.innerHTML = nowCardHTML(ls).trim();
      const newNow = tmp.firstElementChild;
      if (newNow) {
        const label = existingNow.querySelector('.now-label');
        const big = existingNow.querySelector('.now-big');
        const sub = existingNow.querySelector('.now-sub');
        const bar = existingNow.querySelector('.now-bar');

        const newLabel = newNow.querySelector('.now-label');
        const newBig = newNow.querySelector('.now-big');
        const newSub = newNow.querySelector('.now-sub');
        const newBar = newNow.querySelector('.now-bar');

        if (label && newLabel && label.innerHTML !== newLabel.innerHTML) label.innerHTML = newLabel.innerHTML;
        if (big && newBig && big.textContent !== newBig.textContent) big.textContent = newBig.textContent;
        if (sub && newSub && sub.textContent !== newSub.textContent) sub.textContent = newSub.textContent;
        if (bar && newBar) {
          const iOld = bar.querySelector('i');
          const iNew = newBar.querySelector('i');
          if (iOld && iNew) iOld.style.width = iNew.style.width;
        } else if (!bar && newBar) {
          existingNow.appendChild(newBar);
        } else if (bar && !newBar) {
          bar.remove();
        }
      }
    } else {
      const tmp = document.createElement('template');
      tmp.innerHTML = nowCardHTML(ls).trim();
      if (tmp.content.firstChild) container.prepend(tmp.content.firstChild);
    }

    const m = nowMinutes();
    const isLiveDay = s.liveWeek && s.date === s.today;
    const groups = groupLessonsForDisplay(ls);

    groups.forEach((g, gIdx) => {
      const art = container.querySelector(`article.lesson[data-lesson-group="${gIdx}"]`);
      if (!art) return;

      if (g.isGroup) {
        const [lA, lB] = g.lessons;
        const inPart1 = isLiveDay && m >= tm(lA.start) && m < tm(lA.end);
        const inBreak = isLiveDay && m >= tm(lA.end) && m < tm(lB.start);
        const inPart2 = isLiveDay && m >= tm(lB.start) && m <= tm(lB.end);
        const isNow = inPart1 || inBreak || inPart2;
        const isPast = isLiveDay && m > tm(lB.end);

        art.classList.toggle('is-now', isNow);
        art.classList.toggle('is-past', isPast);

        const subTimes = art.querySelectorAll('.tl-sub');
        if (subTimes.length >= 2) {
          subTimes[0].classList.toggle('is-live-target', inPart1);
          subTimes[1].classList.toggle('is-live-target', inPart2);
        }
        const tlBreak = art.querySelector('.tl-break');
        if (tlBreak) {
          tlBreak.classList.toggle('is-break-now', inBreak);
        }

        const currentPhase = inPart1 ? 'part1' : (inBreak ? 'break' : (inPart2 ? 'part2' : (isPast ? 'past' : 'upcoming')));
        const cards = art.querySelectorAll('.deck-card');
        if (art.dataset.livePhase !== currentPhase) {
          art.dataset.livePhase = currentPhase;
          const activeIdx = (inPart2 || inBreak) ? 1 : 0;
          cards.forEach((c, idx) => {
            const isActive = (idx === activeIdx);
            c.classList.toggle('is-active', isActive);
            c.classList.toggle('is-peek', !isActive);
            if (isActive) {
              c.removeAttribute('data-act');
              c.removeAttribute('role');
              c.removeAttribute('tabindex');
              c.removeAttribute('aria-label');
            } else {
              c.setAttribute('data-act', 'pick-subcard');
              c.setAttribute('role', 'button');
              c.setAttribute('tabindex', '0');
              c.setAttribute('aria-label', 'Показать другое занятие');
            }
          });
        }

        if (cards[0]) updateCardLive(cards[0], lA, s, m);
        if (cards[1]) updateCardLive(cards[1], lB, s, m);
      } else {
        const l = g.lessons[0];
        const st = lessonStatus(s, l, s.date);
        art.classList.toggle('is-now', st === 'is-now');
        art.classList.toggle('is-past', st === 'is-past');

        const card = art.querySelector('.deck-card');
        if (card) updateCardLive(card, l, s, m);
      }
    });
  }

  paintAll();
  syncUrl();

  const onTick = () => {
    const s = state();
    if (!s.liveWeek) return;
    if (s.date === s.today) updateLiveStatus(s);
    const gridEl = slot('grid');
    if (gridEl) gridEl.innerHTML = gridHTML(s);
  };

  const timer = setInterval(onTick, 10_000);

  const onVisibilityChange = () => {
    if (document.visibilityState === 'visible') {
      onTick();
    }
  };
  document.addEventListener('visibilitychange', onVisibilityChange);

  root.addEventListener('click', onClick);
  root.addEventListener('submit', onSubmit);
  root.addEventListener('keydown', onKey);
  root.addEventListener('touchstart', onTouchStart, { passive: true });
  root.addEventListener('touchend', onTouchEnd);
  return () => {
    clearInterval(timer);
    document.removeEventListener('visibilitychange', onVisibilityChange);
    root.removeEventListener('click', onClick);
    root.removeEventListener('submit', onSubmit);
    root.removeEventListener('keydown', onKey);
    root.removeEventListener('touchstart', onTouchStart);
    root.removeEventListener('touchend', onTouchEnd);
  };
}
